/**
 * Microsoft OneDrive Node - Version 1.1
 * Discriminator: resource=file, operation=download
 */


interface Credentials {
  microsoftOneDriveOAuth2Api: CredentialReference;
  microsoftOAuth2Api: CredentialReference;
  microsoftEntraServicePrincipalApi: CredentialReference;
}

/** Download a file */
export type MicrosoftOneDriveV11FileDownloadParams = {
  resource: 'file';
  operation: 'download';
  authentication?: 'microsoftOneDriveOAuth2Api' | 'microsoftOAuth2Api' | 'microsoftEntraServicePrincipalApi';
/**
 * Which drive the Service Principal should act on (app-only has no personal drive)
 * @displayOptions.show { authentication: ["microsoftEntraServicePrincipalApi"] }
 * @default user
 */
    resourceTarget?: 'user' | 'drive';
/**
 * The user whose OneDrive the Service Principal should act on. Evaluated per input item, so an expression can target a different user for each item.
 * @displayOptions.show { authentication: ["microsoftEntraServicePrincipalApi"], resourceTarget: ["user"] }
 * @default {"mode":"id","value":""}
 */
    userTarget?: { __rl: true; mode: 'id'; value: string; cachedResultName?: string };
/**
 * The drive the Service Principal should act on. Evaluated per input item, so an expression can target a different drive for each item.
 * @displayOptions.show { authentication: ["microsoftEntraServicePrincipalApi"], resourceTarget: ["drive"] }
 * @default {"mode":"id","value":""}
 */
    driveTarget?: { __rl: true; mode: 'id'; value: string; cachedResultName?: string };
/**
 * File ID
 */
    fileId?: string | Expression<string>;
/**
 * Put Output File in Field
 * @hint The name of the output binary field to put the file in
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
};

export type MicrosoftOneDriveV11FileDownloadOutput = {
  createdBy?: {
    user?: {
      displayName?: string;
      email?: string;
      id?: string;
    };
  };
  createdDateTime?: string;
  file?: {
    hashes?: {
      quickXorHash?: string;
    };
    mimeType?: string;
  };
  fileSystemInfo?: {
    createdDateTime?: string;
    lastModifiedDateTime?: string;
  };
  id?: string;
  lastModifiedBy?: {
    user?: {
      displayName?: string;
      email?: string;
      id?: string;
    };
  };
  lastModifiedDateTime?: string;
  mimeType?: string;
  name?: string;
  parentReference?: {
    driveId?: string;
    driveType?: string;
    id?: string;
    name?: string;
    path?: string;
    siteId?: string;
  };
  path?: string;
  size?: number;
  webUrl?: string;
};

export type MicrosoftOneDriveV11FileDownloadNode = {
  type: 'n8n-nodes-base.microsoftOneDrive';
  version: 1.1;
  config: NodeConfig<MicrosoftOneDriveV11FileDownloadParams> & { credentials?: Credentials };
  output?: Items<MicrosoftOneDriveV11FileDownloadOutput>;
};